void  initValue(SalesType _salesType)
{
    next initValue(_salesType);

    this.ACBookTable = this.salesTable().ACBookTable;
}

public Common ACFantasyBookLookup(FormReferenceControl _formReferenceControl)
{
    SysReferenceTableLookup refTableLookup = SysReferenceTableLookup::newParameters(tableNum(ACBookTable), _formReferenceControl);

    refTableLookup.parmQuery(this.ACGetFantasyBookLookupQuery());
    refTableLookup.addLookupfield(fieldNum(ACBookTable, Id));
    refTableLookup.addLookupfield(fieldNum(ACBookTable, Name));
    refTableLookup.addLookupfield(fieldNum(ACBookTable, Genre));
    refTableLookup.addLookupfield(fieldNum(ACBookTable, Author));

    return refTableLookup.performFormLookup();
}
